function paeth(left, above, diagonal) {
  const estimate = left + above - diagonal;
  const a = Math.abs(estimate - left), b = Math.abs(estimate - above), c = Math.abs(estimate - diagonal);
  return a <= b && a <= c ? left : b <= c ? above : diagonal;
}

async function readPng(body) {
  const data = new Uint8Array(body);
  const view = new DataView(body);
  if (data.length < 33 || view.getUint32(0) !== 0x89504e47 || view.getUint32(4) !== 0x0d0a1a0a) throw new Error('PNG不正');
  const width = view.getUint32(16), height = view.getUint32(20), type = data[25];
  const bpp = { 0:1, 2:3, 3:1, 6:4 }[type];
  if (width !== 1200 || height !== 780 || data[24] !== 8 || !bpp || data[28]) throw new Error('PNG書式違い');
  let palette;
  const chunks = [];
  for (let offset = 8; offset + 12 <= data.length;) {
    const length = view.getUint32(offset);
    const end = offset + 12 + length;
    if (end > data.length) throw new Error('PNG欠落');
    const kind = view.getUint32(offset + 4), chunk = data.subarray(offset + 8, end - 4);
    if (kind === 0x49444154) chunks.push(chunk);
    if (kind === 0x504c5445) palette = chunk;
    if (kind === 0x49454e44) break;
    offset = end;
  }
  if (!chunks.length || (type === 3 && !palette)) throw new Error('PNG画素欠落');

  const stride = width * bpp;
  const lines = 342;
  const bytes = new Uint8Array(lines * (stride + 1));
  const stream = new Blob(chunks).stream().pipeThrough(new DecompressionStream('deflate')).getReader();
  let length = 0;
  try {
    while (length < bytes.length) {
      const { done, value } = await stream.read();
      if (done) throw new Error('PNG画素不足');
      const chunk = value.subarray(0, bytes.length - length);
      bytes.set(chunk, length);
      length += chunk.length;
    }
  } finally {
    await stream.cancel().catch(() => {});
  }

  const gray = new Uint8Array(width * lines);
  let prev = new Uint8Array(stride);
  let row = new Uint8Array(stride);
  for (let y = 0, cursor = 0; y < lines; y++) {
    const filter = bytes[cursor++];
    if (filter > 4) throw new Error('PNGフィルター不正');
    for (let x = 0; x < stride; x++) {
      const left = x < bpp ? 0 : row[x-bpp];
      const above = prev[x];
      const diagonal = x < bpp ? 0 : prev[x-bpp];
      let predicted = 0;
      if (filter === 1) predicted = left;
      else if (filter === 2) predicted = above;
      else if (filter === 3) predicted = (left + above) >> 1;
      else if (filter === 4) predicted = paeth(left,above,diagonal);
      row[x] = bytes[cursor++] + predicted;
    }
    for (let x = 0; x < width; x++) {
      const p = x * bpp;
      if (type === 0) gray[y*width+x] = row[p];
      else {
        const rgb = type === 3 ? palette : row, offset = type === 3 ? row[p]*3 : p;
        gray[y*width+x] = Math.round(0.299*rgb[offset] + 0.587*rgb[offset+1] + 0.114*rgb[offset+2]);
      }
    }
    [prev,row] = [row,prev];
  }
  return { width, height, gray };
}


const TAF_API = 'https://aviationweather.gov/api/data/taf';

function tafTimestamp(value) {
  if (Number.isFinite(value)) return value < 1e12 ? value * 1000 : value;
  return typeof value === 'string' && /(?:Z|[+-]\d{2}:\d{2})$/i.test(value) ? Date.parse(value) : NaN;
}

function tafTime(token, from, to) {
  const date = new Date(from);
  const day = Number(token.slice(0, 2));
  const hour = Number(token.slice(2, 4));
  const minute = Number(token.slice(4) || '0');
  if (day < 1 || day > 31 || hour > 24 || minute > 59 || (hour === 24 && minute > 0)) return NaN;
  for (const monthOffset of [-1, 0, 1]) {
    const midnight = Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + monthOffset, day);
    if (new Date(midnight).getUTCDate() !== day) continue;
    const value = midnight + (hour * 60 + minute) * 60_000;
    if (value >= from && value <= to) return value;
  }
  return NaN;
}

function tafWind(text) {
  const value = /(?:^|\s)((\d{3}|VRB)(P99|\d{2,3})(?:G(P99|\d{2,3}))?(KT|MPS|KMH))(?=\s|$)/.exec(text);
  if (!value) return null;
  const [, raw, direction, speed, gust, unit] = value;
  const factor = { KT: 1, MPS: 1.9438444924, KMH: 1 / 1.852 }[unit];
  const convert = number => Math.round(Number(number.replace('P', '')) * factor);
  const degrees = direction === 'VRB' ? direction : Number(direction);
  if (degrees !== 'VRB' && (degrees > 360 || degrees % 10 !== 0 || (degrees === 0 && convert(speed) > 0))) return null;
  return { raw, direction: degrees, speed: convert(speed), gust: gust ? convert(gust) : null,
    over: speed.startsWith('P'), gustOver: Boolean(gust?.startsWith('P')) };
}

function tafPeriods(report) {
  const { raw, from, to } = report;
  const header = /\b\d{6}Z\s+\d{4}\/\d{4}(?=\s|$)/.exec(raw);
  if (!header || !(from < to)) return [];
  const body = raw.slice(header.index + header[0].length).split(/\sRMK(?:\s|$)|=/)[0];
  const pattern = /\b(?:FM(\d{6})|(BECMG|TEMPO|INTER|PROB(?:30|40)(?:\s+TEMPO)?)\s+(\d{4})\/(\d{4}))(?=\s|$)/g;
  const groups = [...body.matchAll(pattern)];
  if (/\b(?:FM(?=\d)|BECMG\b|TEMPO\b|INTER\b|PROB(?=\d))/.test(body.replace(pattern, ''))) return [];
  const prevailing = [{ time: from, wind: tafWind(body.slice(0, groups[0]?.index ?? body.length)) }];
  const conditional = [];
  for (let i = 0; i < groups.length; i++) {
    const group = groups[i];
    const isFm = Boolean(group[1]);
    const start = tafTime(group[1] || group[3], from, to);
    const end = isFm ? to : tafTime(group[4], from, to);
    if (!(start < end)) return [];
    const wind = tafWind(body.slice(group.index + group[0].length, groups[i + 1]?.index ?? body.length));
    if (isFm) prevailing.push({ time: start, wind });
    else if (wind) {
      const kind = group[2].replace(/\s+/g, ' ');
      conditional.push({ kind, start, end, wind });
      if (kind === 'BECMG') prevailing.push({ time: end, wind });
    }
  }
  const cutoff = Math.max(from, report.issue);
  const boundaries = [...new Set([cutoff, to, ...prevailing.map(p => p.time), ...conditional.flatMap(p => [p.start,p.end])])]
    .filter(time => cutoff <= time && time <= to).sort((a,b) => a-b);
  prevailing.sort((a,b) => a.time-b.time);
  return boundaries.slice(0,-1).flatMap((start,i) => {
    const base = prevailing.findLast(p => p.time <= start)?.wind;
    const changes = conditional.filter(p => p.start <= start && start < p.end);
    if (!base && !changes.length) return [];
    return [{ icao: report.icao, issue: report.issue, from: start, to: boundaries[i+1], base, changes,
      product: 'TAF', source: TAF_API + '?ids=' + report.icao + '&format=raw' }];
  });
}

function validTafRows(reports, codes, now) {
  const latest = new Map();
  const weight = (raw) => /\b(?:CNL|NIL)\b/.test(raw) ? 3 : /\bCOR\b/.test(raw) ? 2 : /\bAMD\b/.test(raw) ? 1 : 0;
  for (const input of reports) {
    const icao = input.icaoId;
    const issue = tafTimestamp(input.issueTime ?? input.bulletinTime);
    const raw = String(input.rawTAF ?? '').trim();
    if (!codes.includes(icao) || !raw || !Number.isFinite(issue) || issue > now + 10 * 60_000) continue;
    const previous = latest.get(icao);
    if (previous && (previous.issue > issue || (previous.issue === issue && weight(previous.raw) >= weight(raw)))) continue;
    latest.set(icao,{icao,issue,raw,from:tafTimestamp(input.validTimeFrom),to:tafTimestamp(input.validTimeTo)});
  }
  return [...latest.values()].flatMap(report => /\b(?:CNL|NIL)\b/.test(report.raw) || report.to <= now ? [] : tafPeriods(report));
}


const IMAGE_ROOT = 'https://www.data.jma.go.jp/airinfo/data/pict/taf/';
const AIRPORT_CODES = Object.keys(AIRPORTS);
const MAX_AGE = 12 * HOUR;
const HEADERS = ['ICAO','開始 JST','終了 JST','予報風 MAG','補足','発表 JST','出典','優先度','原図・原文','更新 JST'];

function freshJmaChart(image, name, now) {
  let chart;
  const dates = ['', ...[0,24].map(h => new Date(now-h*HOUR).toISOString().slice(0,10))];
  for (const date of dates) {
    try {
      chart = readChart(image, name, date, GLYPH_TEMPLATES);
      break;
    } catch (error) {
      if (!error.message.includes('発表月')) throw error;
    }
  }
  if (!chart || chart.part !== 1 || now-chart.issue > MAX_AGE || chart.issue-now > 10*60_000) {
    throw new Error('最新Part 1の発表日時を確認できません');
  }
  return chart;
}

async function fetchJma(icao, fetcher, now) {
  const name = 'QMCD98_' + icao + '.png';
  const source = IMAGE_ROOT + name;
  const response = await fetcher(source, { signal:AbortSignal.timeout(8000), redirect:'error' });
  if (!response.ok || !response.headers.get('content-type')?.toLowerCase().startsWith('image/png')) throw new Error('HTTP ' + response.status);
  const body = await response.arrayBuffer();
  if (body.byteLength > 2_000_000) throw new Error('画像サイズ上限');
  const chart = freshJmaChart(await readPng(body),name,now);
  return chart.rows.filter(row => !row.error && row.base)
    .map(row => ({ ...row, product:'JMA Part 1', source,
      changes: row.tempo ? [{kind:'TEMPO',wind:row.tempo}] : [] }));
}

async function fetchTaf(codes, fetcher, now) {
  const url = new URL(TAF_API);
  url.searchParams.set('ids',codes.join(','));
  url.searchParams.set('format','json');
  const response = await fetcher(url,{signal:AbortSignal.timeout(8000),headers:{'User-Agent':'JMA-aerodrome-wind-feed/1.0','Accept':'application/json'}});
  if (response.status === 204) return [];
  if (!response.ok) throw new Error('HTTP ' + response.status);
  const reports = await response.json();
  if (!Array.isArray(reports)) throw new Error('TAF応答が不正です');
  return validTafRows(reports,codes,now);
}

async function makeFeed({ fetcher = fetch, now = Date.now(), codes = AIRPORT_CODES }={}) {
  const errors = {};
  const beginTaf = fetchTaf(codes,fetcher,now).catch(error=>{errors.taf=error.message;return [];});
  const jma = [];
  for(let offset=0;offset<codes.length;offset+=4) {
    const group = codes.slice(offset,offset+4);
    const batch = await Promise.allSettled(group.map(code=>fetchJma(code,fetcher,now)));
    batch.forEach((item,i)=>{
      if(item.status==='fulfilled' && item.value.length) jma.push(...item.value);
      else errors[group[i]] = item.reason?.message ?? '風が読み取れません';
    });
  }
  const taf = await beginTaf;
  return { generated:now, rows:[...jma,...taf], errors };
}

function label(wind, variation) {
  if (!wind) return '';
  if (wind.direction === 0 && wind.speed === 0) return 'CALM';
  const direction = magneticDirection(wind,variation);
  return direction + ' / ' + (wind.over ? '>' : '') + wind.speed
    + (wind.gust === null ? '' : 'G' + (wind.gustOver ? '>' : '') + wind.gust) + ' kt';
}

function serial(time) {
  return (time + 9*HOUR - Date.UTC(1899,11,30))/(24*HOUR);
}

function csvCell(value) {
  const data = String(value ?? '');
  return /["\r\n,]/.test(data) ? '"' + data.replaceAll('"','""') + '"' : data;
}

function fromFeed(feed) {
  const body = feed.rows.map(row=>{
    const variation = AIRPORTS[row.icao][1];
    const base = label(row.base,variation);
    const conditions = row.changes.map(change=>change.kind+' '+label(change.wind,variation)).join(' | ');
    const changing = row.changes.some(change=>change.kind==='BECMG');
    const display = changing
      ? row.changes.filter(change=>change.kind==='BECMG').map(change=>'BECMG '+(base ? base+' → ' : '')+label(change.wind,variation)).join(' | ')
      : base;
    const notes = changing ? row.changes.filter(change=>change.kind!=='BECMG').map(change=>change.kind+' '+label(change.wind,variation)).join(' | ') : conditions;
    return [row.icao,serial(row.from),serial(row.to),display || notes,display ? notes : '',serial(row.issue),row.product,
      row.product==='TAF' ? 2 : 1,row.source,serial(feed.generated)];
  });
  return [HEADERS,...body].map(row=>row.map(csvCell).join(',')).join('\r\n')+'\r\n';
}

const ROOT_HTML = '<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>飛行場予報風データ</title><main style="max-width:48rem;margin:3rem auto;padding:1rem;font:1rem/1.7 system-ui"><h1>飛行場予報風データ</h1><p>気象庁のPart 1とAviation Weather CenterのTAFを、対象時刻で参照できるCSVにまとめています。</p><p><a href="wind.csv">風データCSV</a> · <a href="health">取得状況</a></p><p>飛行で使用する前に、最新の原図・原文と照合してください。</p></main></html>';
let memory;

async function getFeed(env, ctx) {
  const now = Date.now();
  if (memory && now-memory.time < 5*60_000) return memory.promise;
  const req = new Request('https://jma-wind-feed.internal/weather.json');
  const cache = globalThis.caches?.default;
  const cached = cache ? await cache.match(req).catch(()=>null) : null;
  if (cached) return cached.json();
  const promise = makeFeed().then(result=>{
    if (!result.rows.length) {
      memory = undefined;
      return result;
    }
    if (cache && ctx?.waitUntil) ctx.waitUntil(cache.put(req,Response.json(result,{headers:{'Cache-Control':'public,max-age=300'}})).catch(()=>{}));
    return result;
  },error=>{ memory=undefined; throw error; });
  memory={time:now,promise};
  return promise;
}

export default {
  async fetch(request,env,ctx) {
    const { pathname } = new URL(request.url);
    if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method not allowed',{status:405});
    if (pathname === '/') return new Response(ROOT_HTML,{headers:{'Content-Type':'text/html; charset=utf-8'}});
    if (pathname !== '/wind.csv' && pathname !== '/health') return new Response('Not found',{status:404});
    try {
      const feed=await getFeed(env,ctx);
      if (pathname === '/health') {
        const jma = feed.rows.filter(row=>row.product==='JMA Part 1'), taf = feed.rows.filter(row=>row.product==='TAF');
        return Response.json({generated:new Date(feed.generated).toISOString(),
          jma:{airports:new Set(jma.map(row=>row.icao)).size,periods:jma.length},
          taf:{airports:new Set(taf.map(row=>row.icao)).size,periods:taf.length},errors:feed.errors},
          {status:feed.rows.length ? 200:503,headers:{'Cache-Control':'no-store'}});
      }
      if (!feed.rows.length) return new Response('Weather feed unavailable',{status:503});
      return new Response(request.method === 'HEAD' ? null : fromFeed(feed), {headers:{
        'Content-Type':'text/csv; charset=utf-8','Cache-Control':'public,max-age=300','Access-Control-Allow-Origin':'*'
      }});
    } catch {
      return new Response('Weather feed unavailable',{status:503,headers:{'Cache-Control':'no-store'}});
    }
  }
};
export { makeFeed, fromFeed, tafPeriods, validTafRows, freshJmaChart };



const { mkdir, writeFile } = await import('node:fs/promises');
const out = process.argv[2] || 'public';
const feed = await makeFeed();
const summary = { generated: new Date(feed.generated).toISOString(), jma: 0, taf: 0, errors: feed.errors };
for(const row of feed.rows) {
  if(row.product === 'TAF') summary.taf++;
  else summary.jma++;
}
console.log(JSON.stringify(summary));
if (!feed.rows.length) throw new Error('Both forecast sources are unavailable.');
await mkdir(out,{recursive:true});
await Promise.all([
 writeFile(out+'/wind.csv',fromFeed(feed)),
 writeFile(out+'/index.html',ROOT_HTML.replace('href="health"','href="health.json"')),
 writeFile(out+'/health.json',JSON.stringify(summary,null,2))
]);

